VALUES ('Hajj', 'UB 001', 'Executive Platinum - Intercontinental / Fairmont', '14 Days', 'Dar Al Tawhid Intercontinental / Fairmont Clock Tower (Makkah) - Dar Al Taqwa (Madinah)', 'Intercontinental / Fairmont', '7-19 May 2027 - 1-13 Zil Hajj', 'SAR', 0, 0, 63500, '{"tiers": [{"key": "A", "label": "Dar Al Tawhid Intercontinental"}, {"key": "B", "label": "Fairmont Clock Tower"}], "rooms": [{"room": "Quad", "A": null, "B": 63500}, {"room": "Triple", "A": 94600, "B": 70200}, {"room": "Double", "A": 118500, "B": 85500}]}'::jsonb, 'Non-Aziziya', NULL, 'A 14-day Executive Platinum Hajj (Madinah first) with non-shifting, non-Aziziya accommodation in 5-star hotels in front of the Haram. Choose Package A (Dar Al Tawhid Intercontinental) or Package B (Fairmont Clock Tower) in Makkah, with Dar Al Taqwa in Madinah. Includes premium Maktab A-Category services in Mina Zone 1, near Jamarat.', ARRAY['5-star hotels front of Haram', 'Maktab A - Zone 1 Mina', 'A/C Arafat marquee', 'Train Makkah-Madinah', 'Half-board meals', 'Madinah Ziyarat'], '[{"day": "01", "stage": "In Madinah", "date": "7 May", "hijri": "1 Zil Hajj", "stay": "Dar Al Taqwa 5-star, Madinah"}, {"day": "02", "stage": "In Madinah", "date": "8 May", "hijri": "2 Zil Hajj", "stay": "Dar Al Taqwa 5-star, Madinah"}, {"day": "03", "stage": "In Madinah", "date": "9 May", "hijri": "3 Zil Hajj", "stay": "Dar Al Taqwa 5-star, Madinah"}, {"day": "04", "stage": "In Makkah", "date": "10 May", "hijri": "4 Zil Hajj", "stay": "Travel to Makkah · your chosen 5-star hotel"}, {"day": "05", "stage": "In Makkah", "date": "11 May", "hijri": "5 Zil Hajj", "stay": "5-star Makkah hotel (Umrah & worship)"}, {"day": "06", "stage": "In Makkah", "date": "12 May", "hijri": "6 Zil Hajj", "stay": "5-star Makkah hotel"}, {"day": "07", "stage": "In Makkah", "date": "13 May", "hijri": "7 Zil Hajj", "stay": "5-star Makkah hotel"}, {"day": "08", "stage": "Days of Hajj", "date": "14 May", "hijri": "8 Zil Hajj", "stay": "Mina (Tarwiyah) · Maktab A tent, Zone 1 near Jamarat"}, {"day": "09", "stage": "Days of Hajj", "date": "15 May", "hijri": "9 Zil Hajj", "stay": "Arafat (Wuquf) · A/C marquee, then night in Muzdalifah"}, {"day": "10", "stage": "Days of Hajj", "date": "16 May", "hijri": "10 Zil Hajj", "stay": "Mina (Eid · Rami · Qurbani) · Maktab A tent"}, {"day": "11", "stage": "Days of Hajj", "date": "17 May", "hijri": "11 Zil Hajj", "stay": "Mina (Rami) · Maktab A tent"}, {"day": "12", "stage": "Return to Makkah", "date": "18 May", "hijri": "12 Zil Hajj", "stay": "Return to Makkah · 5-star hotel (Tawaf al-Ifadah)"}, {"day": "13", "stage": "Departure", "date": "19 May", "hijri": "13 Zil Hajj", "stay": "Departure to airport"}]'::jsonb, ARRAY['Meet & assist at the airport (Jeddah / Madinah Hajj Terminal)', 'Group airport transfers to hotel (by Naqaba / Saudi Moallim)', 'Makkah hotel accommodation, half-board (breakfast & dinner)', 'Madinah hotel accommodation, half-board (breakfast & dinner)', 'Full-board buffet meals in Mina (8-12 Zil Hajj)', 'Maktab A-Category tent in Mina, Zone 1 near Jamarat (avg 16/tent, sofa-cum-bed, private toilet)', 'Air-conditioned marquee in Arafat with meals & hot/cold drinks', 'Floor mat & snack box in Muzdalifah', 'Private luxury buses (2025 model) with bathroom for Mashaer days (Mina-Arafat-Muzdalifah)', 'Makkah - Madinah transfer by high-speed train', 'Ziyarat in Madinah with guidance', 'Hajj training & guidance in Pakistan / Saudi Arabia', 'Religious guide book', 'Assistance with Qurbani & Tawaf-e-Ziyara', 'Mic & speaker for religious guidance'], ARRAY['Airline ticket (approx PKR 335,000 from Karachi / PKR 345,000 from North Pakistan)', 'Qurbani (approx SAR 720 per person)', 'Personal expenses & anything not listed under inclusions', 'Optional supplements & upgrades (Deluxe / Diamond tent, Kaaba view, extra Madinah nights, family rooms)'], '{}', 'active', true);

